const task = await folder.file('task.json').readJson();
const decisions: Record<string, Decision> = {};
for (const file of await folder.files('items/*.json')) {
 const item = await file.readJson();
 const caseId = item.id;
 const state = item.state;
 const question = item.question;

 const options = Object.hasOwn(item, 'options') ? item.options : task.options;
 const levels = Object.hasOwn(item, 'levels') ? item.levels : task.levels;
 const decision = await nl<Decision>`Question: ${question}\nAnswer from the scoped state. Choose exactly one answer from the supplied options or levels. Do not return a probability distribution.`(caseId, state, question, options, levels);
 decisions[caseId] = decision;
}
await folder.file(task.output_path).writeText(JSON.stringify(decisions));
return decisions;

